phase1.code:
# Exception handling with try/except/finally

print("=== Basic try/except ===\n")

# Handle division by zero
try:
    x = 10 / 0
    print(f"Result: {x}")
except ZeroDivisionError:
    print("Cannot divide by zero!")

print("Program continues...")

print("\n=== Multiple exceptions ===\n")

# Handle different errors
try:
    num = int("not a number")
    result = 10 / num
except ValueError:
    print("Invalid number format!")
except ZeroDivisionError:
    print("Cannot divide by zero!")

print("\n=== Catching all exceptions ===\n")

try:
    x = 10 / 0
except Exception as e:
    print(f"Error occurred: {e}")
    print(f"Type: {type(e).__name__}")

print("\n=== try/except/else/finally ===\n")

try:
    x = 10 / 2
except ZeroDivisionError:
    print("Cannot divide by zero!")
else:
    print(f"Division successful: {x}")
finally:
    print("This always runs!")

print("\n=== Raising exceptions ===\n")

def check_age(age):
    if age < 0:
        raise ValueError("Age cannot be negative!")
    if age > 150:
        raise ValueError("Age too high!")
    return f"Age {age} is valid"

try:
    print(check_age(25))
    print(check_age(-5))
except ValueError as e:
    print(f"Error: {e}")

phase3.solution:
def divide_numbers(a, b):
    if b == 0:
        raise ValueError("Cannot divide by zero")
    return a / b

try:
    print(divide_numbers(10, 2))
    print(divide_numbers(10, 0))
    print(divide_numbers(10, "5"))
except ValueError as e:
    print(f"Error: {e}")
except TypeError:
    print("Error: Invalid type for division")
except Exception as e:
    print(f"Unexpected error: {e}")
finally:
    print("Division attempt completed")
